/*
 * A281426  Numerator of n-th term of sequence (or tree) S of all rational
 *          numbers generated by these rules: 0 is in S; if x is in S then x +
 *          1 is in S, and if x + 1 is nonzero, then -1/(x + 1) is in S;
 *          duplicates are deleted as they occur.
 * https://oeis.org/A281426
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  frac, sign
 * Formula:   not stated
 * Range:     i8 n <= 1000, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A281426: numerator of the n‑th term of the tree of rationals
   generated by: 0 ∈ S; if x ∈ S then x+1 ∈ S and, if x+1 ≠ 0,
   then –1/(x+1) ∈ S. Duplicates are removed in the order in which
   they would appear.  The function a(n) returns the numerator of
   a(n) for 1 ≤ n.  */
/* The implementation uses a breadth‑first walk of the directed
   graph, keeping a visited table to avoid duplicates.  All arithmetic
   is performed with seq_t, but intermediate sums are computed in
   __int128 to prevent overflow when seq_t is 64‑bit. */
#include <stddef.h>
#include <stdbool.h>
#include "../utils/gcd.h"

/* Maximum number of terms that may appear while generating up to
   10 000 indices.  These limits are generous enough for the
   required N and prevent buffer overruns. */
#define MAX_CACHE 200000      /* size of a[] array storing numerators      */
#define MAX_VISITED 200000    /* size of visited rational table           */

/* Rational number stored with a positive denominator */
typedef struct {
    seq_t num;
    seq_t den;
} rat_t;

/* Return the numerator of the n‑th term of the sequence */
seq_t a(idx_t n)
{
    if (n <= 0) return 0;        /* safety for offset 1 */

    /* Persistent state shared between calls */
    static bool initialized = false;
    static seq_t cache[MAX_CACHE];
    static size_t cache_len = 0;

    static rat_t visited[MAX_VISITED];
    static size_t visited_len = 0;

    static rat_t queue[MAX_VISITED];
    static size_t queue_head = 0, queue_tail = 0;

    if (!initialized) {
        /* Seed with the initial rational 0/1 */
        queue[queue_tail++] = (rat_t){ 0, 1 };
        visited[visited_len++] = (rat_t){ 0, 1 };
        initialized = true;
    }

    /* Consume from the queue until we have generated at least n terms */
    while (cache_len < (size_t)n) {
        /* Take the next rational from the queue */
        if (queue_head >= queue_tail) break;   /* should never happen */
        rat_t cur = queue[queue_head++];

        /* Record its numerator */
        cache[cache_len++] = cur.num;

        /* Generate children */
        /* 1. x + 1 */
        __int128 temp_sum = (__int128)cur.num + (__int128)cur.den;
        seq_t sum = (seq_t)temp_sum;      /* fits in seq_t or lower */

        /* Reduce (x+1) to lowest terms */
        seq_t g1 = gcd(sum, cur.den);
        seq_t num1 = sum / g1;
        seq_t den1 = cur.den / g1;
        if (den1 < 0) { den1 = -den1; num1 = -num1; }

        /* Check if this rational is new */
        bool duplicate = false;
        for (size_t i = 0; i < visited_len; ++i) {
            if (visited[i].num == num1 && visited[i].den == den1) {
                duplicate = true; break;
            }
        }
        if (!duplicate) {
            visited[visited_len++] = (rat_t){ num1, den1 };
            queue[queue_tail++]   = (rat_t){ num1, den1 };
        }

        /* 2. –1/(x+1), only if x+1 ≠ 0 */
        if (sum != 0) {
            seq_t num2 = -cur.den;
            seq_t den2 = sum;
            seq_t g2   = gcd(num2, den2);
            num2 /= g2; den2 /= g2;
            if (den2 < 0) { den2 = -den2; num2 = -num2; }

            duplicate = false;
            for (size_t i = 0; i < visited_len; ++i) {
                if (visited[i].num == num2 && visited[i].den == den2) {
                    duplicate = true; break;
                }
            }
            if (!duplicate) {
                visited[visited_len++] = (rat_t){ num2, den2 };
                queue[queue_tail++]   = (rat_t){ num2, den2 };
            }
        }
    }

    return cache[(size_t)n - 1];
}
